// ORACLE — Organization Members API
// GET  /api/organizations/members — list members of current org
// POST /api/organizations/members — invite member to current org
// ═══════════════════════════════════════

import { NextResponse } from 'next/server';
import { validateAuth } from '@/lib/supabase/validate';
import { inviteMember, roleAtLeast, hasPermissionSync } from '@/lib/permissions';
import { createLogger } from '@/lib/logger';

const log = createLogger('OrgMembers');

export async function GET() {
  const auth = await validateAuth();
  if ('error' in auth) return auth.error;
  if (!auth.org) {
    return NextResponse.json({ error: 'No organization context' }, { status: 400 });
  }

  try {
    const { supabase } = auth;
    const { data, error } = await supabase
      .from('organization_memberships')
      .select(`
        user_id,
        role,
        joined_at,
        invited_by
      `)
      .eq('org_id', auth.org.orgId);

    if (error) {
      log.error('Failed to list members', { error: error.message, orgId: auth.org.orgId });
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json({
      members: data ?? [],
      orgId: auth.org.orgId,
      yourRole: auth.org.role,
    });
  } catch (err) {
    log.error('Failed to list members', {
      error: err instanceof Error ? err.message : 'Unknown',
      orgId: auth.org.orgId,
    });
    return NextResponse.json({ error: 'Failed to list members' }, { status: 500 });
  }
}

export async function POST(request: Request) {
  const auth = await validateAuth();
  if ('error' in auth) return auth.error;
  if (!auth.org) {
    return NextResponse.json({ error: 'No organization context' }, { status: 400 });
  }

  // Check permission
  const perm = hasPermissionSync(auth.org.role, 'INVITE_MEMBERS');
  if (!perm.allowed) {
    return NextResponse.json({ error: perm.reason }, { status: 403 });
  }

  try {
    const { email, role } = await request.json();

    if (!email || typeof email !== 'string') {
      return NextResponse.json({ error: 'Email is required' }, { status: 400 });
    }

    const validRoles = ['owner', 'admin', 'employee', 'client'];
    if (!role || !validRoles.includes(role)) {
      return NextResponse.json(
        { error: `Role must be one of: ${validRoles.join(', ')}` },
        { status: 400 }
      );
    }

    // Owners can assign any role; admins can only assign employee or client
    if (auth.org.role === 'admin' && roleAtLeast(role as any, 'admin')) {
      return NextResponse.json(
        { error: 'Admins can only invite employees or clients' },
        { status: 403 }
      );
    }

    const result = await inviteMember(auth.org.orgId, email, role, auth.user.id);

    if (!result.success) {
      return NextResponse.json({ error: result.error }, { status: 400 });
    }

    log.info('Member invited via API', { orgId: auth.org.orgId, email, role });

    return NextResponse.json({ success: true, email, role }, { status: 201 });
  } catch (err) {
    log.error('Failed to invite member', {
      error: err instanceof Error ? err.message : 'Unknown',
      orgId: auth.org.orgId,
    });
    return NextResponse.json({ error: 'Failed to invite member' }, { status: 500 });
  }
}

// ═══════════════════════════════════════
// ORACLE — Organizations API
// POST /api/organizations — create org
// GET  /api/organizations — list user's orgs
// ═══════════════════════════════════════

import { NextResponse } from 'next/server';
import { validateAuth } from '@/lib/supabase/validate';
import { createOrganization } from '@/lib/permissions';
import { createLogger } from '@/lib/logger';

const log = createLogger('Organizations');

export async function POST(request: Request) {
  const auth = await validateAuth();
  if ('error' in auth) return auth.error;

  try {
    const { name, slug } = await request.json();

    if (!name || typeof name !== 'string' || name.trim().length === 0) {
      return NextResponse.json({ error: 'Organization name is required' }, { status: 400 });
    }

    if (!slug || typeof slug !== 'string' || slug.trim().length === 0) {
      return NextResponse.json({ error: 'Organization slug is required' }, { status: 400 });
    }

    // Validate slug format (lowercase alphanumeric + hyphens)
    if (!/^[a-z0-9-]+$/.test(slug)) {
      return NextResponse.json(
        { error: 'Slug must be lowercase alphanumeric with hyphens only' },
        { status: 400 }
      );
    }

    const result = await createOrganization(name.trim(), slug.trim(), auth.user.id);

    if ('error' in result) {
      return NextResponse.json({ error: result.error }, { status: 500 });
    }

    log.info('Organization created via API', { orgId: result.orgId, name, slug });

    return NextResponse.json({ orgId: result.orgId, name, slug }, { status: 201 });
  } catch (err) {
    log.error('Failed to create organization', {
      error: err instanceof Error ? err.message : 'Unknown',
      userId: auth.user.id,
    });
    return NextResponse.json({ error: 'Failed to create organization' }, { status: 500 });
  }
}

export async function GET() {
  const auth = await validateAuth();
  if ('error' in auth) return auth.error;

  try {
    const { supabase } = auth;
    const { data, error } = await supabase
      .from('organization_memberships')
      .select(`
        role,
        joined_at,
        organizations (
          id,
          name,
          slug,
          created_at
        )
      `)
      .eq('user_id', auth.user.id);

    if (error) {
      log.error('Failed to list organizations', { error: error.message, userId: auth.user.id });
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    const organizations = (data ?? []).map((m: any) => ({
      orgId: m.organizations?.id,
      name: m.organizations?.name,
      slug: m.organizations?.slug,
      role: m.role,
      joinedAt: m.joined_at,
      createdAt: m.organizations?.created_at,
    })).filter((o: any) => o.orgId);

    return NextResponse.json({ organizations });
  } catch (err) {
    log.error('Failed to list organizations', {
      error: err instanceof Error ? err.message : 'Unknown',
      userId: auth.user.id,
    });
    return NextResponse.json({ error: 'Failed to list organizations' }, { status: 500 });
  }
}

/**
 * Shared test utilities for API route handlers.
 *
 * Each test file must:
 * 1. Import this file first
 * 2. Call vi.mock('@/lib/supabase/validate', ...) at top level with vi.hoisted
 * 3. Then import route handlers
 */

import { vi } from 'vitest';

// ─── Mock next/server ───

vi.mock('next/server', () => {
  class MockNextResponse {
    body: unknown;
    init: { status?: number };
    constructor(body?: unknown, init?: { status?: number }) {
      this.body = body;
      this.init = init ?? {};
    }
    static json(body: unknown, init?: { status?: number }) {
      return { body, init, _type: 'NextResponse' };
    }
  }
  return { NextResponse: MockNextResponse };
});

// ─── MockResponse type ───

export interface MockResponse {
  body: unknown;
  init?: { status?: number };
  status?: number;
}

export function castMockResponse(res: unknown): MockResponse {
  return res as MockResponse;
}

// ─── NextRequest factories ───

export function createGetRequest(url = 'http://localhost/api/test') {
  return { url } as unknown as import('next/server').NextRequest;
}

export function createPostRequest(body: unknown, url = 'http://localhost/api/test') {
  return {
    url,
    json: async () => body,
  } as unknown as import('next/server').NextRequest;
}

export function createPutRequest(body: unknown, url = 'http://localhost/api/test') {
  return {
    url,
    json: async () => body,
  } as unknown as import('next/server').NextRequest;
}

// ─── Mock Supabase Client ───

/**
 * Factory that creates a `setupChain` function bound to the given hoisted mocks.
 *
 * Usage in test file:
 * ```ts
 * const { from, authMock } = vi.hoisted(() => ({ from: vi.fn(), authMock: vi.fn() }));
 * vi.mock('@/lib/supabase/validate', () => ({ validateAuth: (...a: any[]) => authMock(...a) }));
 * import { GET } from './route';
 * const setupChain = makeSetupChain(from, authMock);
 * ```
 */
export function makeSetupChain(from: any, authMock: any) {
  return function setupChain(res?: { data?: unknown; error?: unknown }) {
    const result = { data: res?.data ?? [], error: res?.error ?? null };
    const spy = () => c;
    const c: any = {
      select: vi.fn(spy), insert: vi.fn(spy), update: vi.fn(spy), delete: vi.fn(spy),
      order: vi.fn(spy), eq: vi.fn(spy), limit: vi.fn(spy),
      single: vi.fn().mockResolvedValue(result),
      then: (ok: any, fail?: any) => { if (result.error) fail?.(result.error); else ok(result); },
    };
    from.mockReturnValue(c);
    authMock.mockResolvedValue({ user: { id: 'u1' }, supabase: { from, auth: { getUser: vi.fn() }, _chain: c }, org: { orgId: 'org-test-001', role: 'owner' } });
    return c;
  };
}

'use client';

import React, { useState, useCallback, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { motionVariants, transitions, buttonTapProps } from '@/styles/design-tokens';
import {
  addBrandAsset,
  getBrandAssets,
  deleteBrandAsset,
  getAssetsByClient,
  hexToRgb,
  getContrastColor,
  getAssetTypeIcon,
  getAssetTypeLabel,
  COMMON_FONTS,
  getFontPairings,
} from '@/lib/brand-asset-library';
import type { BrandAsset, AssetType } from '@/lib/brand-asset-library';

// ─── BrandAssetsPanel ─────────────────

export function BrandAssetsPanel() {
  const [refreshKey, setRefreshKey] = useState(0);
  const [showForm, setShowForm] = useState(false);
  const [selectedClient, setSelectedClient] = useState<string | null>(null);

  const allAssets = useMemo(() => getBrandAssets(), [refreshKey]);
  const byClient = useMemo(() => getAssetsByClient(), [refreshKey]);
  const clientNames = Object.keys(byClient);

  const filteredAssets = useMemo(() => {
    if (selectedClient) return allAssets.filter((a) => a.clientName === selectedClient);
    return allAssets;
  }, [allAssets, selectedClient]);

  const handleAdd = useCallback((data: Omit<BrandAsset, 'id' | 'createdAt'>) => {
    addBrandAsset(data);
    setShowForm(false);
    setRefreshKey((k) => k + 1);
  }, []);

  const handleDelete = useCallback((id: string) => {
    deleteBrandAsset(id);
    setRefreshKey((k) => k + 1);
  }, []);

  return (
    <div className="flex h-full flex-col overflow-hidden">
      <div className="flex-1 overflow-y-auto px-4 py-6">
        <div className="mx-auto max-w-4xl space-y-6">
          {/* Header */}
          <motion.div variants={motionVariants.fadeUp} initial="initial" animate="animate" transition={transitions.smooth}>
            <div className="flex items-center justify-between">
              <div>
                <h1 className="text-[22px] font-bold text-[var(--oracle-text-1)]">🎨 Brand Assets</h1>
                <p className="mt-1 text-[13px] text-[var(--oracle-text-3)]">
                  Manage client logos, colors, fonts, and brand guidelines
                </p>
              </div>
              <motion.button
                {...buttonTapProps}
                onClick={() => setShowForm(!showForm)}
                className="flex items-center justify-center gap-2 rounded-xl oracle-gradient-bg px-4 py-2.5 text-[13px] font-semibold text-white transition-all"
              >
                {showForm ? '✕ Close' : '+ Add Asset'}
              </motion.button>
            </div>
          </motion.div>

          {/* Stats Row */}
          <motion.div variants={motionVariants.fadeUp} initial="initial" animate="animate" transition={transitions.smooth}>
            <div className="grid grid-cols-2 gap-3 md:grid-cols-4">
              <StatCard icon="🎨" label="Logos" value={String(allAssets.filter((a) => a.type === 'logo').length)} />
              <StatCard icon="🎨" label="Colors" value={String(allAssets.filter((a) => a.type === 'color').length)} />
              <StatCard icon="🔤" label="Fonts" value={String(allAssets.filter((a) => a.type === 'font').length)} />
              <StatCard icon="📁" label="Clients" value={String(clientNames.length)} />
            </div>
          </motion.div>

          {/* Client Filter */}
          {clientNames.length > 0 && (
            <motion.div variants={motionVariants.fadeUp} initial="initial" animate="animate" transition={transitions.smooth}>
              <div className="flex items-center gap-2 flex-wrap">
                <button
                  onClick={() => setSelectedClient(null)}
                  className={`rounded-full px-3 py-1.5 text-[11px] font-medium transition-colors ${!selectedClient ? 'oracle-gradient-bg text-white' : 'border border-[var(--oracle-border)] text-[var(--oracle-text-3)] hover:bg-[var(--oracle-card-hover)]'}`}
                >
                  All ({allAssets.length})
                </button>
                {clientNames.map((name) => (
                  <button
                    key={name}
                    onClick={() => setSelectedClient(name === selectedClient ? null : name)}
                    className={`rounded-full px-3 py-1.5 text-[11px] font-medium transition-colors ${selectedClient === name ? 'oracle-gradient-bg text-white' : 'border border-[var(--oracle-border)] text-[var(--oracle-text-3)] hover:bg-[var(--oracle-card-hover)]'}`}
                  >
                    {name} ({byClient[name].length})
                  </button>
                ))}
              </div>
            </motion.div>
          )}

          {/* Add Form */}
          <AnimatePresence>
            {showForm && (
              <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} transition={transitions.smooth}>
                <AddAssetForm onSubmit={handleAdd} onCancel={() => setShowForm(false)} />
              </motion.div>
            )}
          </AnimatePresence>

          {/* Font Pairings Reference */}
          <motion.div variants={motionVariants.fadeUp} initial="initial" animate="animate" transition={transitions.smooth}>
            <div className="oracle-glass rounded-2xl p-5">
              <h3 className="mb-3 text-[15px] font-bold text-[var(--oracle-text-1)]">🔤 Font Pairing Reference</h3>
              <div className="space-y-2">
                {COMMON_FONTS.slice(0, 6).map((font) => (
                  <div key={font.name} className="flex items-center gap-3 rounded-lg bg-[var(--oracle-surface-2)] p-2">
                    <span className="w-32 text-[12px] font-semibold text-[var(--oracle-text-1)]">{font.name}</span>
                    <span className="text-[10px] text-[var(--oracle-text-muted)]">{font.category} · {font.style}</span>
                    <span className="ml-auto text-[10px] text-[var(--oracle-info)]">
                      Pairs: {getFontPairings(font.name).slice(0, 2).join(', ')}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          </motion.div>

          {/* Assets Grid */}
          {filteredAssets.length > 0 && (
            <motion.div variants={motionVariants.fadeUp} initial="initial" animate="animate" transition={transitions.smooth}>
              <div className="oracle-glass rounded-2xl p-5">
                <h3 className="mb-4 text-[15px] font-bold text-[var(--oracle-text-1)]">📋 Assets ({filteredAssets.length})</h3>
                <div className="space-y-2">
                  {filteredAssets.map((asset) => (
                    <div key={asset.id} className="flex items-center gap-3 rounded-xl border border-[var(--oracle-border)] p-3">
                      {/* Color swatch or icon */}
                      {asset.type === 'color' ? (
                        <div
                          className="h-10 w-10 shrink-0 rounded-lg border border-[var(--oracle-border)]"
                          style={{ backgroundColor: asset.value }}
                          title={asset.value}
                        />
                      ) : asset.type === 'font' ? (
                        <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-[var(--oracle-surface-2)]">
                          <span className="text-lg">{getAssetTypeIcon(asset.type)}</span>
                        </div>
                      ) : (
                        <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-[var(--oracle-surface-2)]">
                          <span className="text-lg">{getAssetTypeIcon(asset.type)}</span>
                        </div>
                      )}

                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-1">
                          <span className="text-[13px] font-semibold text-[var(--oracle-text-1)]">{asset.name}</span>
                          <span className="rounded-full px-2 py-0.5 text-[10px] font-medium bg-[var(--oracle-surface-2)] text-[var(--oracle-text-muted)]">
                            {getAssetTypeLabel(asset.type)}
                          </span>
                          <span className="text-[10px] text-[var(--oracle-text-muted)]">{asset.clientName}</span>
                        </div>
                        {asset.type === 'color' && (
                          <div className="flex items-center gap-2">
                            <span className="font-mono text-[11px] text-[var(--oracle-text-3)]">{asset.value}</span>
                            {hexToRgb(asset.value) && (
                              <span className="text-[10px] text-[var(--oracle-text-muted)]">
                                RGB({hexToRgb(asset.value)!.r}, {hexToRgb(asset.value)!.g}, {hexToRgb(asset.value)!.b})
                              </span>
                            )}
                            <div
                              className="h-4 w-4 rounded border border-[var(--oracle-border)]"
                              style={{ backgroundColor: getContrastColor(asset.value), color: asset.value }}
                            >
                              <span className="flex items-center justify-center text-[8px] font-bold">A</span>
                            </div>
                          </div>
                        )}
                        {asset.type === 'font' && (
                          <span className="text-[11px] text-[var(--oracle-text-3)]">{asset.value}</span>
                        )}
                      </div>

                      <button
                        onClick={() => handleDelete(asset.id)}
                        className="shrink-0 rounded-lg p-1.5 text-[var(--oracle-text-muted)] hover:bg-[var(--oracle-card-hover)] hover:text-[var(--oracle-error)] transition-colors"
                        aria-label={`Delete ${asset.name}`}
                      >
                        ✕
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            </motion.div>
          )}

          {/* Empty State */}
          {allAssets.length === 0 && (
            <motion.div variants={motionVariants.fadeUp} initial="initial" animate="animate" transition={transitions.smooth} className="py-8 text-center">
              <div className="mb-4 mx-auto flex h-20 w-20 items-center justify-center rounded-2xl bg-[var(--oracle-surface-2)]">
                <span className="text-4xl">🎨</span>
              </div>
              <h3 className="mb-2 text-[18px] font-bold text-[var(--oracle-text-1)]">No Brand Assets Yet</h3>
              <p className="max-w-md mx-auto text-[14px] text-[var(--oracle-text-3)]">
                Click &quot;Add Asset&quot; to store client logos, colors, fonts, and other brand guidelines.
              </p>
            </motion.div>
          )}
        </div>
      </div>
    </div>
  );
}

// ─── Add Asset Form ───────────────────

function AddAssetForm({
  onSubmit,
  onCancel,
}: {
  onSubmit: (data: Omit<BrandAsset, 'id' | 'createdAt'>) => void;
  onCancel: () => void;
}) {
  const [clientName, setClientName] = useState('');
  const [type, setType] = useState<AssetType>('color');
  const [name, setName] = useState('');
  const [value, setValue] = useState('');
  const [tags, setTags] = useState('');

  const handleSubmit = () => {
    if (!clientName.trim() || !name.trim() || !value.trim()) return;
    onSubmit({
      projectId: 'manual',
      clientName: clientName.trim(),
      type,
      name: name.trim(),
      value: value.trim(),
      tags: tags.split(',').map((t) => t.trim()).filter(Boolean),
    });
  };

  return (
    <div className="oracle-glass rounded-2xl p-5">
      <h3 className="mb-4 text-[15px] font-bold text-[var(--oracle-text-1)]">📝 Add Brand Asset</h3>
      <div className="space-y-4">
        <div className="grid grid-cols-2 gap-3">
          <input value={clientName} onChange={(e) => setClientName(e.target.value)} placeholder="Client name" className="rounded-xl border border-[var(--oracle-border)] bg-[var(--oracle-surface-2)] px-4 py-2.5 text-[13px] text-[var(--oracle-text-1)] placeholder:text-[var(--oracle-text-muted)] outline-none focus:border-[var(--oracle-primary)]" />
          <select value={type} onChange={(e) => setType(e.target.value as AssetType)} className="rounded-xl border border-[var(--oracle-border)] bg-[var(--oracle-surface-2)] px-3 py-2 text-[12px] text-[var(--oracle-text-2)] outline-none">
            <option value="color">🎨 Color</option>
            <option value="font">🔤 Font</option>
            <option value="logo">🖼 Logo</option>
            <option value="image">🖼 Image</option>
            <option value="document">📄 Document</option>
          </select>
        </div>

        <input value={name} onChange={(e) => setName(e.target.value)} placeholder="Asset name (e.g. Primary Blue, Heading Font)" className="w-full rounded-xl border border-[var(--oracle-border)] bg-[var(--oracle-surface-2)] px-4 py-2.5 text-[13px] text-[var(--oracle-text-1)] placeholder:text-[var(--oracle-text-muted)] outline-none focus:border-[var(--oracle-primary)]" />

        {type === 'color' ? (
          <div className="flex items-center gap-3">
            <input value={value} onChange={(e) => setValue(e.target.value)} placeholder="#6366f1" className="flex-1 rounded-xl border border-[var(--oracle-border)] bg-[var(--oracle-surface-2)] px-4 py-2.5 font-mono text-[13px] text-[var(--oracle-text-1)] placeholder:text-[var(--oracle-text-muted)] outline-none focus:border-[var(--oracle-primary)]" />
            <input type="color" value={value || '#6366f1'} onChange={(e) => setValue(e.target.value)} className="h-10 w-10 shrink-0 rounded-lg border border-[var(--oracle-border)] cursor-pointer" />
          </div>
        ) : type === 'font' ? (
          <select value={value} onChange={(e) => setValue(e.target.value)} className="w-full rounded-xl border border-[var(--oracle-border)] bg-[var(--oracle-surface-2)] px-3 py-2.5 text-[12px] text-[var(--oracle-text-2)] outline-none">
            <option value="">Select a font...</option>
            {COMMON_FONTS.map((f) => (
              <option key={f.name} value={f.name}>{f.name} ({f.style})</option>
            ))}
          </select>
        ) : (
          <input value={value} onChange={(e) => setValue(e.target.value)} placeholder="URL or data URL" className="w-full rounded-xl border border-[var(--oracle-border)] bg-[var(--oracle-surface-2)] px-4 py-2.5 text-[13px] text-[var(--oracle-text-1)] placeholder:text-[var(--oracle-text-muted)] outline-none focus:border-[var(--oracle-primary)]" />
        )}

        <input value={tags} onChange={(e) => setTags(e.target.value)} placeholder="Tags (comma separated)" className="w-full rounded-xl border border-[var(--oracle-border)] bg-[var(--oracle-surface-2)] px-4 py-2.5 text-[13px] text-[var(--oracle-text-1)] placeholder:text-[var(--oracle-text-muted)] outline-none focus:border-[var(--oracle-primary)]" />

        <div className="flex items-center justify-end gap-2">
          <motion.button {...buttonTapProps} onClick={onCancel} className="rounded-xl border border-[var(--oracle-border)] px-4 py-2 text-[12px] text-[var(--oracle-text-3)] hover:bg-[var(--oracle-card-hover)] transition-colors">
            Cancel
          </motion.button>
          <motion.button {...buttonTapProps} onClick={handleSubmit} disabled={!clientName.trim() || !name.trim() || !value.trim()} className="rounded-xl oracle-gradient-bg px-6 py-2 text-[12px] font-semibold text-white transition-all disabled:opacity-40">
            Save Asset
          </motion.button>
        </div>
      </div>
    </div>
  );
}

// ─── Stat Card ────────────────────────

function StatCard({ icon, label, value }: { icon: string; label: string; value: string }) {
  return (
    <div className="oracle-glass rounded-xl p-4">
      <div className="flex items-center gap-2 mb-2">
        <span className="text-lg">{icon}</span>
        <span className="text-[11px] text-[var(--oracle-text-muted)]">{label}</span>
      </div>
      <p className="text-[20px] font-bold text-[var(--oracle-text-1)]">{value}</p>
    </div>
  );
}

'use client';

import React, { useRef, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import { estimateTokens } from '@/lib/utils';
import { AGENT_TYPES, type AgentType } from './agent-config';
import { DailyUsageIndicator, useSubscriptionState } from './FeatureGate';
import { hasAgentAccess } from '@/lib/subscription';
import type { ChatMessage } from './MessageBubble';

// ─── Chat Input Area ───────────────────

interface ChatInputAreaProps {
  input: string;
  setInput: React.Dispatch<React.SetStateAction<string>>;
  isStreaming: boolean;
  agentType: AgentType;
  setAgentType: (type: AgentType) => void;
  attachments: Array<{ name: string; content: string }>;
  setAttachments: React.Dispatch<React.SetStateAction<Array<{ name: string; content: string }>>>;
  estimatedCost: { inr: number; usd: number; isFree: boolean } | null;
  detectedPatterns: Array<{ category: string; confidence: number; matchedKeywords: string[] }>;
  crossDomainSuggestions: Array<{ service: string; relevance: number; rationale: string; value: string }>;
  dailyUsage?: { used: number; limit: number } | null;
  onSend: (overrideContent?: string) => void;
  onPaste: (e: React.ClipboardEvent) => void;
  onFileAttach: (e: React.ChangeEvent<HTMLInputElement>) => void;
  onSidebarToggle?: () => void;
  sidebarOpen?: boolean;
}

export function ChatInputArea({
  input, setInput, isStreaming, agentType, setAgentType,
  attachments, setAttachments, estimatedCost,
  detectedPatterns, crossDomainSuggestions, dailyUsage,
  onSend, onPaste, onFileAttach,
  onSidebarToggle, sidebarOpen,
}: ChatInputAreaProps) {
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const { plan } = useSubscriptionState();
  const agentAllowed = hasAgentAccess(plan, agentType);

  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      onSend();
    }
  }, [onSend]);

  return (
    <div className="border-t border-[var(--oracle-border)] bg-[var(--oracle-bg)]/80 backdrop-blur-xl p-3 sm:p-4">
      {/* Sidebar Toggle */}
      {onSidebarToggle && (
        <div className="mb-2 flex justify-end">
          <button
            onClick={onSidebarToggle}
            aria-label={sidebarOpen ? 'Hide sidebar' : 'Show sidebar'}
            className="rounded-lg border border-[var(--oracle-border)] px-2 py-1 text-[11px] text-[var(--oracle-text-muted)] hover:border-[var(--oracle-border-strong)] hover:text-[var(--oracle-text-3)] transition-colors min-h-[36px]"
          >
            {sidebarOpen ? '→ Hide sidebar' : '← Show sidebar'}
          </button>
        </div>
      )}
      <div className="mx-auto max-w-3xl">
        {/* Agent Badge */}
        {(() => {
          const agentInfo = AGENT_TYPES.find((a) => a.id === agentType);
          if (!agentInfo) return null;
          const isOrchestrator = agentType === 'orchestrator';
          const locked = !agentAllowed;
          return (
            <div className={`mb-2 flex items-center gap-2 rounded-lg border px-3 py-2 ${
              locked
                ? 'bg-[var(--oracle-warning)]/5 border-[var(--oracle-warning)]/20'
                : isOrchestrator
                  ? 'bg-[var(--oracle-surface-2)]/60 border-[var(--oracle-border)]'
                  : 'bg-[var(--oracle-primary)]/5 border-[var(--oracle-primary)]/15'
            }`}>
              {locked && <span className="text-sm">🔒</span>}
              {!locked && <span className="text-sm">{agentInfo.emoji}</span>}
              <span className={`text-[11px] font-semibold ${
                locked
                  ? 'text-[var(--oracle-warning)]'
                  : isOrchestrator
                    ? 'text-[var(--oracle-text-3)]'
                    : 'text-[var(--oracle-primary-l)]'
              }`}>{agentInfo.label} Agent</span>
              {locked && (
                <span className="text-[10px] text-[var(--oracle-warning)] hidden sm:inline">· Requires {plan === 'starter' ? 'Pro' : 'Agency'} plan</span>
              )}
              {!locked && (
                <span className="text-[10px] text-[var(--oracle-text-muted)] hidden sm:inline">· {isOrchestrator ? 'Multi-agent orchestrator mode' : 'Specialized system prompt loaded'}</span>
              )}
              {locked ? (
                <a
                  href="/pricing"
                  className="oracle-cta-pulse ml-auto rounded-md px-2 py-0.5 text-[10px] font-medium text-[var(--oracle-primary)] hover:bg-[var(--oracle-card-hover)] transition-colors"
                >
                  Upgrade →
                </a>
              ) : !isOrchestrator ? (
                <button
                  onClick={() => setAgentType('orchestrator')}
                  className="ml-auto rounded-md px-2 py-0.5 text-[10px] text-[var(--oracle-text-muted)] hover:bg-[var(--oracle-card-hover)] hover:text-[var(--oracle-text-3)] transition-colors"
                >
                  Switch to Orchestrator
                </button>
              ) : null}
            </div>
          );
        })()}

        {/* Attachment Pills */}
        {attachments.length > 0 && (
          <div className="mb-2 flex flex-wrap gap-2">
            {attachments.map((a, i) => (
              <span
                key={i}
                className="flex items-center gap-1.5 rounded-full bg-[var(--oracle-surface-2)] px-3 py-1 text-[12px] text-[var(--oracle-text-2)]"
              >
                📎 {a.name}
                <button
                  onClick={() => setAttachments((prev) => prev.filter((_, j) => j !== i))}
                  className="text-[var(--oracle-text-muted)] hover:text-[var(--oracle-error)] min-h-[44px] min-w-[44px] flex items-center justify-center -m-3"
                  aria-label={`Remove attachment ${a.name}`}
                >
                  ×
                </button>
              </span>
            ))}
          </div>
        )}

        {/* Daily Usage Indicator */}
        {dailyUsage && dailyUsage.limit > 0 && (
          <div className="mb-2 flex items-center gap-2 rounded-lg bg-[var(--oracle-surface-2)]/60 px-3 py-1.5">
            <span className="text-[10px] text-[var(--oracle-text-muted)]">📊 Today:</span>
            <DailyUsageIndicator used={dailyUsage.used} limit={dailyUsage.limit} />
            {dailyUsage.used >= dailyUsage.limit && (
              <a href="/pricing" className="text-[10px] font-medium text-[var(--oracle-primary)] hover:underline">Upgrade →</a>
            )}
          </div>
        )}

        {/* Cost Estimate */}
        {estimatedCost && input.trim() && (
          <div className="mb-2 flex items-center gap-2 rounded-lg bg-[var(--oracle-surface-2)]/60 px-3 py-1.5">
            <span className="text-[10px] text-[var(--oracle-text-muted)]">💰 Est. cost:</span>
            {estimatedCost.isFree ? (
              <span className="text-[10px] font-medium text-[var(--oracle-success)]">FREE (free tier model)</span>
            ) : (
              <span className="text-[10px] font-mono text-[var(--oracle-text-muted)]">
                ₹{estimatedCost.inr.toFixed(2)} (${estimatedCost.usd.toFixed(4)})
              </span>
            )}
            <span className="text-[10px] text-[var(--oracle-text-muted)]">·</span>
            <span className="text-[10px] text-[var(--oracle-text-muted)]">{estimateTokens(input)} tokens</span>
          </div>
        )}

        {/* Pattern Recognition & Cross-Domain Suggestions */}
        {(detectedPatterns.length > 0 || crossDomainSuggestions.length > 0) && input.length > 10 && (
          <div className="mb-2 space-y-1.5">
            {detectedPatterns.length > 0 && (
              <div className="flex flex-wrap items-center gap-1.5 rounded-lg bg-[var(--oracle-surface-2)]/60 px-3 py-1.5">
                <span className="text-[10px] text-[var(--oracle-text-muted)]">🏷️ Detected:</span>
                {detectedPatterns.map((p, i) => (
                  <span key={i} className="rounded-full bg-[var(--oracle-primary)]/10 px-2 py-0.5 text-[10px] font-medium text-[var(--oracle-primary-l)]">
                    {p.category.replace(/-/g, ' ')} ({p.confidence}%)
                  </span>
                ))}
              </div>
            )}
            {crossDomainSuggestions.length > 0 && (
              <div className="rounded-lg bg-[var(--oracle-surface-2)]/60 px-3 py-2">
                <p className="mb-1 text-[10px] text-[var(--oracle-text-muted)]">🔗 Adjacent services to consider:</p>
                <div className="flex flex-wrap gap-1.5">
                  {crossDomainSuggestions.map((s, i) => (
                    <span key={i} className="rounded-full bg-[var(--oracle-success)]/10 px-2 py-0.5 text-[10px] font-medium text-[var(--oracle-success)]" title={s.rationale}>
                      + {s.service} ({s.value})
                    </span>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}

        {/* Input Container */}
        <div className="oracle-glass rounded-2xl border border-[var(--oracle-border-strong)] p-2">
          <div className="flex items-end gap-2">
            {/* Action Buttons */}
            <div className="flex items-center gap-1 pb-1.5">
              <motion.button
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                onClick={() => document.getElementById('file-input')?.click()}
                aria-label="Attach document"
                className="flex h-11 w-11 items-center justify-center rounded-lg text-[var(--oracle-text-muted)] hover:bg-[var(--oracle-card-hover)] hover:text-[var(--oracle-text-3)] transition-colors"
              >
                <span className="text-base" aria-hidden="true">📎</span>
              </motion.button>
              <motion.button
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                onClick={() => {
                  if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
                    const SpeechRecognition = (window as unknown as { webkitSpeechRecognition: unknown }).webkitSpeechRecognition || (window as unknown as { SpeechRecognition: unknown }).SpeechRecognition;
                    const recognition = new (SpeechRecognition as new () => { lang: string; continuous: boolean; onresult: (e: { results: Array<{ isFinal: boolean; length: number; item: (i: number) => { transcript: string } }> }) => void; start: () => void; stop: () => void })();
                    recognition.lang = 'en-IN';
                    recognition.continuous = false;
                    recognition.onresult = (e: { results: Array<{ isFinal: boolean; length: number; item: (i: number) => { transcript: string } }> }) => {
                      if (e.results[0]?.isFinal) {
                        setInput((prev) => prev + ' ' + e.results[0].item(0).transcript);
                      }
                    };
                    recognition.start();
                  }
                }}
                aria-label="Voice input"
                className="flex h-11 w-11 items-center justify-center rounded-lg text-[var(--oracle-text-muted)] hover:bg-[var(--oracle-card-hover)] hover:text-[var(--oracle-text-3)] transition-colors"
              >
                <span className="text-base" aria-hidden="true">🎙</span>
              </motion.button>
            </div>

            {/* Textarea */}
            <textarea
              ref={inputRef}
              data-chat-input
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              onPaste={onPaste}
              placeholder="Describe any agency task... (Ctrl+V to paste images)"
              rows={1}
              aria-label="Chat input"
              className="flex-1 resize-none bg-transparent py-2 text-[15px] text-[var(--oracle-text-1)] placeholder:text-[var(--oracle-text-muted)] outline-none min-h-[48px] max-h-[120px]"
              style={{ height: 'auto' }}
              onInput={(e) => {
                const target = e.target as HTMLTextAreaElement;
                target.style.height = 'auto';
                target.style.height = Math.min(target.scrollHeight, 120) + 'px';
              }}
            />

            {/* Send Button */}
            <button
              onClick={() => onSend()}
              disabled={!input.trim() || isStreaming}
              aria-label="Send message"
              className="flex h-11 w-11 items-center justify-center rounded-xl oracle-gradient-bg text-white transition-all disabled:opacity-30 disabled:cursor-not-allowed hover:scale-105 active:scale-95 mb-0.5"
            >
              {isStreaming ? (
                <div className="h-4 w-4 animate-spin rounded-full border-2 border-white/30 border-t-white" />
              ) : (
                <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
                  <path d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z" />
                </svg>
              )}
            </button>
          </div>
        </div>

        {/* Hidden File Input */}
        <input
          id="file-input"
          type="file"
          className="hidden"
          accept=".pdf,.docx,.xlsx,.xls,.txt,.md,.csv,.json,.jpg,.jpeg,.png,.webp"
          multiple
          onChange={onFileAttach}
        />
      </div>
    </div>
  );
}

'use client';

import React, { useState, useRef, useCallback, useEffect, useMemo } from 'react';
import {AnimatePresence} from 'framer-motion';
import { NeverStopRouter } from '@/lib/router';
import { useRouterStore } from '@/stores/router.store';
import { conversationsApi, knowledgeDocsApi, projectsApi, memoriesApi } from '@/lib/api';
import { processDocument, retrieveRelevant, chunkText, indexDocument } from '@/lib/rag';
import { sanitizeDocumentContent, sanitizeSearchResults, sanitizeExternalContext } from '@/lib/prompt-sanitizer';
import { getMemories, formatMemoryForContext } from '@/lib/memory';
import { QUALITY_SCORING_PROMPT } from '@/lib/system-prompt';
import { saveQualityScore } from '@/lib/quality';
import {runHallucinationGuard, loadGuardConfig} from '@/lib/hallucination-guard';
import { evaluateOutput, type EvalResult, type ThresholdConfig } from '@/lib/output-quality-evaluator';
import { runEditorGate, type EditorGateResult } from '@/lib/editor-gate';
import { calculateAllCosts } from '@/lib/token-budget';
import { buildOptimizedContext, type ContextMessage } from '@/lib/context-manager';
import { estimateTokens } from '@/lib/utils';
import { exportChatToPDF, exportChatToWord } from '@/lib/export-utils';
import { formatSearchResults } from '@/lib/search';
import { csrfHeaders } from '@/lib/csrf';
import { recordTask } from '@/lib/self-training';
import { recordProviderHealth } from '@/lib/provider-health';
import { attachQualityToTraining, recordMessageFeedback } from '@/lib/feedback-bridge';
import { getAdjacentServices } from '@/lib/cross-domain-thinking';
import { recogniseTaskPatterns } from '@/lib/pattern-recognition';
import { runQualityGates, runOperatingLoop, type QualityGateResult, type OperatingLoopResult } from '@/lib/agency-operations';
import { analyzeTask } from '@/lib/task-analyzer';
import { OperatingLoopStepDots, OperatingLoopFloatingProgress } from '@/components/oracle/OperatingLoopDashboard';

import toast from 'react-hot-toast';
import { TOAST_DEFAULTS } from '@/lib/toast-config';
import {useSubscriptionState} from '@/components/oracle/FeatureGate';
import { GuardStatsPanel } from '@/components/oracle/GuardStatsPanel';
import { AGENT_TYPES, AGENT_SYSTEM_PROMPTS, type AgentType, type ConversationSummary, type ProjectSummary } from '@/components/oracle/agent-config';
import { ChatHeader } from '@/components/oracle/ChatHeader';
import { ChatInputArea } from '@/components/oracle/ChatInputArea';
import { EmptyState } from '@/components/oracle/EmptyState';
import { MessageBubble, type ChatMessage } from '@/components/oracle/MessageBubble';
import type { QualityScore, KnowledgeDocument, MemoryItem, HallucinationCheckResult } from '@/types';
import { nanoid } from 'nanoid';

// ─── Chat Panel ────────────────────────

interface ChatPanelProps {
  onSidebarToggle?: () => void;
  sidebarOpen?: boolean;
  activeProjectId?: string | null;
  webSearchEnabled?: boolean;
}

export function ChatPanel({ onSidebarToggle, sidebarOpen, activeProjectId, webSearchEnabled: webSearchProp }: ChatPanelProps) {
  // Core state
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const messagesRef = useRef<ChatMessage[]>([]);
  messagesRef.current = messages;
  const [input, setInput] = useState('');
  const [isStreaming, setIsStreaming] = useState(false);
  const [attachments, setAttachments] = useState<Array<{ name: string; content: string }>>([]);

  // Conversation state
  const [conversations, setConversations] = useState<ConversationSummary[]>([]);
  const [activeConversationId, setActiveConversationId] = useState<string | null>(null);
  const [conversationTitle, setConversationTitle] = useState('New Chat');

  // Agent state
  const [agentType, setAgentType] = useState<AgentType>('orchestrator');
  const [showAgentSelector, setShowAgentSelector] = useState(false);
  const [showConversationList, setShowConversationList] = useState(false);

  // Project state
  const [projects, setProjects] = useState<ProjectSummary[]>([]);
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('oracle_selected_project_id');
    }
    return null;
  });
  const [showProjectSelector, setShowProjectSelector] = useState(false);

  // Context state
  const [knowledgeDocs, setKnowledgeDocs] = useState<KnowledgeDocument[]>([]);
  const [clientMemories, setClientMemories] = useState<MemoryItem[]>([]);

  // Quality state
  const [qualityScores, setQualityScores] = useState<Record<string, QualityScore>>({});

  // Hallucination guard state
  const [guardResults, setGuardResults] = useState<Record<string, HallucinationCheckResult>>({});

  // Output quality evaluator state
  const [evalResults, setEvalResults] = useState<Record<string, EvalResult>>({});

  // Editor gate state
  const [editorResults, setEditorResults] = useState<Record<string, EditorGateResult>>({});

  // Agency quality gate state
  const [qualityGateResults, setQualityGateResults] = useState<Record<string, QualityGateResult>>({});

  // Operating loop state
  const [operatingLoopResults, setOperatingLoopResults] = useState<Record<string, OperatingLoopResult[]>>({});

  // Active operating loop real-time state (for the floating progress indicator)
  const [activeLoopProgress, setActiveLoopProgress] = useState<OperatingLoopResult[]>([]);
  const [activeLoopTask, setActiveLoopTask] = useState('');
  const [isLoopActive, setIsLoopActive] = useState(false);

  // Feedback state (persisted in localStorage)
  const [feedback, setFeedback] = useState<Record<string, 'good' | 'bad'>>(() => {
    if (typeof window !== 'undefined') {
      try {
        const raw = localStorage.getItem('oracle_message_feedback');
        return raw ? JSON.parse(raw) : {};
      } catch { return {}; }
    }
    return {};
  });

  // Cost estimation state
  const [estimatedCost, setEstimatedCost] = useState<{ inr: number; usd: number; isFree: boolean } | null>(null);

  // Web search state
  const [webSearchEnabled, setWebSearchEnabled] = useState(webSearchProp ?? false);
  const [searchContext, setSearchContext] = useState('');

  // Cross-domain suggestions state
  const [crossDomainSuggestions, setCrossDomainSuggestions] = useState<Array<{ service: string; relevance: number; rationale: string; value: string }>>([]);

  // Pattern recognition state
  const [detectedPatterns, setDetectedPatterns] = useState<Array<{ category: string; confidence: number; matchedKeywords: string[] }>>([]);

  // Drag-and-drop state
  const [isDragging, setIsDragging] = useState(false);

  // Daily usage state
  const [dailyUsage, setDailyUsage] = useState<{ used: number; limit: number } | null>(null);
  const dailyUsageRef = useRef<{ used: number; limit: number } | null>(null);
  const { plan } = useSubscriptionState();

  // Star reactions (persisted in localStorage)
  const [starredMessages, setStarredMessages] = useState<Record<string, boolean>>(() => {
    if (typeof window !== 'undefined') {
      try {
        const raw = localStorage.getItem('oracle_starred_messages');
        return raw ? JSON.parse(raw) : {};
      } catch { return {}; }
    }
    return {};
  });

  // Refs
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const loopAbortRef = useRef<AbortController | null>(null);

  // Store
  const { streamingEnabled, addCost, addUsageRecord, configuredProviders } = useRouterStore();

  // ── Fetch daily usage on mount and after each message ──
  const fetchDailyUsage = useCallback(async () => {
    try {
      const res = await fetch('/api/subscription/status');
      if (res.ok) {
        const data = await res.json();
        if (data.usage) {
          const usage = { used: data.usage.used ?? 0, limit: data.usage.limit ?? -1 };
          setDailyUsage(usage);
          dailyUsageRef.current = usage;

          // Show warning toast at 80% (only once per threshold)
          if (usage.limit > 0) {
            const pct = (usage.used / usage.limit) * 100;
            const prevPct = dailyUsageRef.current
              ? (dailyUsageRef.current.used / dailyUsageRef.current.limit) * 100
              : 0;
            if (pct >= 80 && prevPct < 80) {
              toast(`⚠️ You've used ${usage.used}/${usage.limit} daily requests. Upgrade for unlimited.`, {
                duration: 6000,
                icon: '⚠️',
              });
            }
          }
        }
      }
    } catch {
      // Non-critical — fail silently
    }
  }, []);

  // Fetch on mount
  useEffect(() => {
    fetchDailyUsage();
  }, [fetchDailyUsage]);

  // ── Load conversations on mount ──
  useEffect(() => {
    conversationsApi.list().then((rows) => {
      setConversations(rows.map((r) => ({
        id: r.id,
        title: r.title,
        agentType: r.agent_type,
        messageCount: Array.isArray(r.messages) ? r.messages.length : 0,
        createdAt: r.created_at,
        updatedAt: r.updated_at,
      })));
    }).catch(() => { toast.error('❌ Failed to load conversations', TOAST_DEFAULTS); });

    knowledgeDocsApi.list().then((rows) => {
      setKnowledgeDocs(rows.map((r) => ({
        id: r.id,
        name: r.name,
        content: r.content,
        chunks: chunkText(r.content),
        source: r.source as 'upload',
        createdAt: r.created_at,
        tags: r.tags || [],
      })));
    }).catch(() => { toast.error('❌ Failed to load knowledge docs', TOAST_DEFAULTS); });

    projectsApi.list().then(async (rows) => {
      const projectList = rows.map((r) => ({
        id: r.id,
        clientName: r.client_name,
        industry: r.industry,
        service: r.service,
        status: r.status as ProjectSummary['status'],
        memoryCount: 0,
      }));
      setProjects(projectList);
      const counts = await Promise.all(
        projectList.map(async (p) => {
          try {
            const memories = await memoriesApi.list(p.id);
            return { id: p.id, count: memories.length };
          } catch (err) {
            toast.error('❌ Failed to load project memories', TOAST_DEFAULTS);
            return { id: p.id, count: 0 };
          }
        })
      );
      const updated = projectList.map((p) => {
        const found = counts.find((c) => c.id === p.id);
        return found ? { ...p, memoryCount: found.count } : p;
      });
      setProjects(updated);
      window.dispatchEvent(new CustomEvent('oracle-projects-update', { detail: { projects: updated } }));
    }).catch(() => { toast.error('❌ Failed to load projects', TOAST_DEFAULTS); });
  }, []);

  // ── Auto-scroll ──
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // ── Cross-domain & pattern recognition on input change (debounced) ──
  useEffect(() => {
    if (!input.trim() || input.length < 10) {
      setCrossDomainSuggestions([]);
      setDetectedPatterns([]);
      return;
    }
    const timer = setTimeout(() => {
      const patterns = recogniseTaskPatterns(input, 3);
      setDetectedPatterns(patterns.map((p) => ({
        category: p.category,
        confidence: p.confidence,
        matchedKeywords: p.matchedKeywords,
      })));

      const serviceKeywords = ['seo', 'website', 'ads', 'social media', 'email', 'content', 'crm', 'brand', 'analytics'];
      const mentionedServices = serviceKeywords.filter((s) => input.toLowerCase().includes(s));
      if (mentionedServices.length > 0) {
        const suggestions = getAdjacentServices(mentionedServices[0], 70).slice(0, 3);
        setCrossDomainSuggestions(suggestions.map((s) => ({
          service: s.adjacentService,
          relevance: s.relevance,
          rationale: s.rationale,
          value: s.estimatedValue,
        })));
      } else {
        setCrossDomainSuggestions([]);
      }
    }, 500);
    return () => clearTimeout(timer);
  }, [input]);

  // ── Cost estimation when input changes ──
  const cheapestModelCost = useMemo(() => {
    const costs = calculateAllCosts();
    const freeModels = costs.filter((c) => c.isFree);
    const cheapestFree = freeModels.length > 0
      ? freeModels.reduce((a, b) => (a.fullRequestCostINR <= b.fullRequestCostINR ? a : b))
      : null;
    if (cheapestFree) return { inr: 0, usd: 0, isFree: true };
    const cheapest = costs.reduce((a, b) => (a.fullRequestCostINR <= b.fullRequestCostINR ? a : b));
    return { inr: cheapest.fullRequestCostINR, usd: cheapest.fullRequestCostUSD, isFree: false };
  }, []);

  useEffect(() => {
    if (!input.trim()) { setEstimatedCost(null); return; }
    if (cheapestModelCost.isFree) {
      setEstimatedCost({ inr: 0, usd: 0, isFree: true });
    } else {
      const inputTokens = estimateTokens(input);
      const ratio = inputTokens / 500;
      setEstimatedCost({
        inr: Math.round(cheapestModelCost.inr * ratio * 100) / 100,
        usd: Math.round(cheapestModelCost.usd * ratio * 10000) / 10000,
        isFree: false,
      });
    }
  }, [input, cheapestModelCost]);

  // ── Persist feedback to localStorage ──
  useEffect(() => {
    if (typeof window !== 'undefined') {
      localStorage.setItem('oracle_message_feedback', JSON.stringify(feedback));
    }
  }, [feedback]);

  // ── Persist starred messages ──
  useEffect(() => {
    if (typeof window !== 'undefined') {
      localStorage.setItem('oracle_starred_messages', JSON.stringify(starredMessages));
    }
  }, [starredMessages]);

  // ── Persist selected project to localStorage ──
  useEffect(() => {
    if (selectedProjectId) {
      localStorage.setItem('oracle_selected_project_id', selectedProjectId);
    } else {
      localStorage.removeItem('oracle_selected_project_id');
    }
  }, [selectedProjectId]);

  // ── Load memories when project changes ──
  const effectiveProjectId = selectedProjectId || activeProjectId;
  useEffect(() => {
    if (effectiveProjectId) {
      getMemories(effectiveProjectId).then(setClientMemories).catch(() => { toast('⚠️ Failed to load client memories', TOAST_DEFAULTS); setClientMemories([]); });
    } else {
      setClientMemories([]);
    }
    window.dispatchEvent(new CustomEvent('oracle-project-select', { detail: { projectId: effectiveProjectId } }));
  }, [effectiveProjectId]);

  // ── Load conversation ──
  const loadConversation = useCallback(async (id: string) => {
    try {
      const convo = await conversationsApi.get(id);
      setMessages(convo.messages.map((m) => ({
        ...m,
        isStreaming: false,
        agentType: (m.agentType || 'orchestrator') as AgentType,
      })));
      setActiveConversationId(id);
      setConversationTitle(convo.title);
      setAgentType((convo.agent_type as AgentType) || 'orchestrator');
      setShowConversationList(false);
      // Reset persist tracking — all loaded messages are already in the DB
      persistedCountRef.current = convo.messages.length;
    } catch {
      toast.error('❌ Failed to load conversation', TOAST_DEFAULTS);
    }
  }, []);

  // ── New conversation ──
  const newConversation = useCallback(() => {
    setMessages([]);
    setActiveConversationId(null);
    setConversationTitle('New Chat');
    setAgentType('orchestrator');
    setQualityScores({});
    setGuardResults({});
    setEvalResults({});
    setEditorResults({});
    setQualityGateResults({});
    setOperatingLoopResults({});
    setActiveLoopProgress([]);
    setActiveLoopTask('');
    setIsLoopActive(false);
    setShowConversationList(false);
    persistedCountRef.current = 0;
  }, []);

  // ── Refresh conversation list ──
  const refreshConversations = useCallback(async () => {
    try {
      const rows = await conversationsApi.list();
      setConversations(rows.map((r) => ({
        id: r.id,
        title: r.title,
        agentType: r.agent_type,
        messageCount: Array.isArray(r.messages) ? r.messages.length : 0,
        createdAt: r.created_at,
        updatedAt: r.updated_at,
      })));
    } catch {
      toast.error('❌ Failed to refresh conversations', TOAST_DEFAULTS);
    }
  }, []);

  // ── Save conversation ──
  // Track which messages have already been persisted to avoid re-sending them.
  const persistedCountRef = useRef(0);
  // When branching/regenerating, the DB state diverges from our incremental count;
  // this flag forces a full array replacement on the next save.
  const needsFullSyncRef = useRef(false);

  const saveConversation = useCallback(async (msgs: ChatMessage[], title: string, agent: string) => {
    const serializable = msgs.map((m) => ({
      id: m.id,
      role: m.role as 'user' | 'assistant',
      content: m.content,
      timestamp: m.timestamp,
      provider: m.provider,
      model: m.model,
      tokensUsed: m.tokensUsed,
      qualityScore: m.qualityScore,
      agentType: m.agentType,
    }));

    try {
      if (activeConversationId) {
        if (needsFullSyncRef.current) {
          // Branch/regenerate: DB state diverged, replace entire array
          await conversationsApi.update(activeConversationId, {
            title,
            messages: serializable,
            agent_type: agent,
          });
          needsFullSyncRef.current = false;
          persistedCountRef.current = serializable.length;
        } else {
          // Normal flow: incremental append of new messages only
          const newMsgs = serializable.slice(persistedCountRef.current);
          if (newMsgs.length > 0) {
            await conversationsApi.appendMessages(activeConversationId, newMsgs);
            persistedCountRef.current = serializable.length;
          }
        }
      } else {
        const created = await conversationsApi.create({
          title,
          messages: serializable,
          agent_type: agent,
        });
        setActiveConversationId(created.id);
        persistedCountRef.current = serializable.length;
        refreshConversations();
      }
    } catch {
      toast.error('❌ Failed to save conversation', TOAST_DEFAULTS);
    }
  }, [activeConversationId, refreshConversations]);

  // ── Build context for AI ──
  const buildAIContext = useCallback(async (userMessage: string): Promise<{ systemPrompt?: string; documents: string[]; searchUsed: boolean }> => {
    const parts: string[] = [];
    const documents: string[] = [];
    let searchUsed = false;

    if (knowledgeDocs.length > 0) {
      const relevantChunks = await retrieveRelevant(userMessage, knowledgeDocs, 3);
      if (relevantChunks.length > 0) {
        // Sanitize each chunk to prevent document-based prompt injection
        const sanitizedChunks = relevantChunks.map((chunk, i) => {
          const result = sanitizeDocumentContent(chunk, `knowledge_base_${i}`);
          return result.sanitized;
        });
        parts.push('## Knowledge Base Context\n' + sanitizedChunks.join('\n\n'));
        documents.push(...sanitizedChunks);
      }
    }

    if (clientMemories.length > 0) {
      const memoryContext = formatMemoryForContext(clientMemories);
      if (memoryContext) {
        parts.push('## Client Memory\n' + memoryContext);
      }
    }

    const agentSystemPrompt = AGENT_SYSTEM_PROMPTS[agentType];
    if (agentSystemPrompt) {
      const agentInfo = AGENT_TYPES.find((a) => a.id === agentType);
      parts.push(`## Agent Mode: ${agentInfo?.label || agentType}\n\n${agentSystemPrompt}`);
    }

    if (webSearchEnabled && userMessage.length > 5) {
      try {
        const proxyResponse = await fetch('/api/web-search', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', ...csrfHeaders() },
          body: JSON.stringify({ query: userMessage, provider: 'tavily', maxResults: 5 }),
        });
        if (proxyResponse.ok) {
          const data = await proxyResponse.json();
          const results = data.results || [];
          if (results.length > 0) {
            // Sanitize search results to prevent search-result-based prompt injection
            const sanitizedResults = sanitizeSearchResults(results);
            const formatted = formatSearchResults(sanitizedResults);
            parts.push('## Web Search Results\n' + formatted);
            documents.push(...sanitizedResults.map((r) => `${r.title}: ${r.snippet}`));
            setSearchContext(formatted);
            searchUsed = true;
          }
        }
      } catch {
        // Web search failed silently
      }
    } else {
      setSearchContext('');
    }

    return {
      systemPrompt: parts.length > 0 ? parts.join('\n\n') : undefined,
      documents,
      searchUsed,
    };
  }, [knowledgeDocs, clientMemories, agentType, webSearchEnabled]);

  // ── Optimize messages for context window ──
  const getOptimizedMessages = useCallback((msgs: ChatMessage[]): Array<{ role: string; content: string }> => {
    const contextMsgs: ContextMessage[] = msgs.map((m) => ({
      id: m.id, role: m.role, content: m.content, timestamp: m.timestamp,
    }));
    const managed = buildOptimizedContext(contextMsgs, { maxTokens: 8000, recentMessageCount: 10 });
    return managed.messages;
  }, []);

  // ── Export handlers ──
  const handleExportPDF = useCallback(() => {
    if (messages.length === 0) { toast.error('No messages to export', TOAST_DEFAULTS); return; }
    exportChatToPDF(messages, conversationTitle);
    toast.success('✅ PDF exported', TOAST_DEFAULTS);
  }, [messages, conversationTitle]);

  const handleExportWord = useCallback(() => {
    if (messages.length === 0) { toast.error('No messages to export', TOAST_DEFAULTS); return; }
    exportChatToWord(messages, conversationTitle);
    toast.success('✅ Word document exported', TOAST_DEFAULTS);
  }, [messages, conversationTitle]);

  // ── Star message ──
  const handleStar = useCallback((msgId: string) => {
    setStarredMessages((prev) => {
      const next = { ...prev };
      if (next[msgId]) { delete next[msgId]; } else { next[msgId] = true; }
      return next;
    });
  }, []);

  // ── Drag and drop handlers ──
  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, [])

  const handleDrop = useCallback(async (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const files = Array.from(e.dataTransfer.files);
    for (const file of files) {
      try {
        const doc = await processDocument(file);
        indexDocument(doc).catch(() => {}); // fire-and-forget embedding indexing
        setAttachments((prev) => [...prev, { name: file.name, content: doc.content }]);
      } catch {
        toast.error(`❌ Failed to read ${file.name}`, TOAST_DEFAULTS);
      }
    }
  }, []);

  // ── Clipboard paste handler ──
  const handlePaste = useCallback(async (e: React.ClipboardEvent) => {
    const items = Array.from(e.clipboardData.items);
    for (const item of items) {
      if (item.type.startsWith('image/')) {
        const file = item.getAsFile();
        if (file) {
          try {
            const doc = await processDocument(file);
            indexDocument(doc).catch(() => {}); // fire-and-forget embedding indexing
            setAttachments((prev) => [...prev, { name: file.name || 'clipboard-image.png', content: doc.content }]);
            toast.success('📋 Image pasted from clipboard', TOAST_DEFAULTS);
          } catch {
            toast.error('❌ Failed to read pasted image', TOAST_DEFAULTS);
          }
        }
      }
    }
  }, []);

  // ── Record Usage ──
  const recordUsage = useCallback((provider: string, model: string, inputTokens: number, outputTokens: number, costUSD: number) => {
    const cost = NeverStopRouter.calculateCost(provider, model, inputTokens, outputTokens);
    if (costUSD > 0 || cost.inr > 0) {
      addCost(costUSD || cost.usd, cost.inr);
    }
    addUsageRecord({
      id: nanoid(),
      timestamp: Date.now(),
      provider,
      model,
      inputTokens,
      outputTokens,
      costUSD: costUSD || cost.usd,
      costINR: cost.inr,
      taskType: agentType,
    });
  }, [addCost, addUsageRecord, agentType]);

  // ── Hallucination Guard (async, non-blocking) ──
  const runGuardCheck = useCallback(async (userContent: string, aiContent: string, msgId: string, docChunks: string[]) => {
    const guardConfig = loadGuardConfig();
    if (!guardConfig.enabled) return;
    try {
      const result = await runHallucinationGuard(
        aiContent,
        userContent,
        {
          documentChunks: docChunks,
          searchResults: [],
          memory: clientMemories.map((m) => ({ content: m.content, category: m.category })),
          domain: undefined,
        },
        guardConfig,
      );
      setGuardResults((prev) => ({ ...prev, [msgId]: result }));
    } catch (err) {
      toast('⚠️ Hallucination guard check failed', TOAST_DEFAULTS);
    }
  }, [clientMemories]);

  // ── Load evaluator thresholds from localStorage ──
  const loadEvalThresholds = useCallback((): Partial<ThresholdConfig> | undefined => {
    if (typeof window === 'undefined') return undefined;
    try {
      const raw = localStorage.getItem('oracle-eval-thresholds');
      if (!raw) return undefined;
      return JSON.parse(raw) as Partial<ThresholdConfig>;
    } catch {
      return undefined;
    }
  }, []);

  // ── Output Quality Evaluator (async, non-blocking) ──
  const runOutputEval = useCallback(async (aiContent: string, msgId: string) => {
    try {
      const thresholds = loadEvalThresholds();
      const result = evaluateOutput(aiContent, { thresholds });
      setEvalResults((prev) => ({ ...prev, [msgId]: result }));
      // Show warning toast if score is below threshold
      if (!result.passed) {
        toast(`⚠️ Output quality: ${result.overallScore}/100 — ${result.suggestions[0] || 'Review suggestions'}`, {
          ...TOAST_DEFAULTS,
          duration: 4000,
        });
      }
    } catch {
      // Evaluator is non-critical; fail silently
    }
  }, [loadEvalThresholds]);

  // ── Agency Quality Gate (sync, non-blocking) ──
  const runAgencyQualityGate = useCallback((userContent: string, aiContent: string, msgId: string) => {
    try {
      const result = runQualityGates(aiContent, userContent);
      setQualityGateResults((prev) => ({ ...prev, [msgId]: result }));
      if (!result.passed) {
        const failedChecks = result.checks.filter(c => !c.passed).map(c => c.name).join(', ');
        toast(`⚠️ Quality gate: ${result.score}/100 — Failed: ${failedChecks}`, {
          ...TOAST_DEFAULTS,
          duration: 4000,
        });
      }
    } catch {
      // Quality gate is non-critical; fail silently
    }
  }, []);

  // ── Editor Gate (async, non-blocking) ──
  const runEditorCheck = useCallback(async (userContent: string, aiContent: string, msgId: string) => {
    try {
      const result = await runEditorGate(userContent, aiContent, agentType, configuredProviders);
      setEditorResults((prev) => ({ ...prev, [msgId]: result }));
      // Auto-apply corrected text if editor found issues and provided a fix
      if (!result.passed && result.correctedText && result.correctedText.length > 0) {
        setMessages((prev) =>
          prev.map((m) =>
            m.id === msgId ? { ...m, content: result.correctedText! } : m
          )
        );
        toast(`✏️ Editor gate applied ${result.issues.length} correction(s)`, {
          ...TOAST_DEFAULTS,
          duration: 3000,
        });
      }
    } catch {
      // Editor gate is non-critical; fail silently
    }
  }, [agentType, configuredProviders]);

  // ── Compute average quality score ──
  useEffect(() => {
    const scores = Object.values(qualityScores);
    if (scores.length > 0) {
      const avg = Math.round(scores.reduce((s, q) => s + q.total, 0) / scores.length);
      window.dispatchEvent(new CustomEvent('oracle-quality-update', { detail: { score: avg } }));
    }
  }, [qualityScores]);

  // ── Quality Score (async, non-blocking) ──
  const scoreResponse = useCallback(async (userContent: string, aiContent: string, msgId: string) => {
    try {
      const prompt = QUALITY_SCORING_PROMPT
        .replace('{{response}}', aiContent)
        .replace('{{taskContext}}', userContent);

      const providerId = configuredProviders.length > 0 ? configuredProviders[0] : 'groq';

      const proxyResponse = await fetch('/api/ai/chat', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-oracle-provider-id': providerId,
          ...csrfHeaders(),
        },
        body: JSON.stringify({
          messages: [{ role: 'user', content: prompt }],
          maxTokens: 500,
          stream: false,
        }),
      });

      if (!proxyResponse.ok) return undefined;
      const proxyResult = await proxyResponse.json();
      const text = proxyResult.text || '';

      const jsonMatch = text.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        const score = JSON.parse(jsonMatch[0]) as QualityScore;
        score.scoredAt = Date.now();
        setQualityScores((prev) => ({ ...prev, [msgId]: score }));
        saveQualityScore(score);
        return score;
      }
    } catch {
      // Quality scoring is non-critical; fail silently
    }
    return undefined;
  }, [configuredProviders]);

  // ── Send Message ──
  const handleSend = useCallback(async (overrideContent?: string) => {
    const messageText = overrideContent ?? input.trim();
    if (!messageText || isStreaming) return;

    let messageContent = messageText;
    if (!overrideContent && attachments.length > 0) {
      // Sanitize each attachment to prevent attachment-based prompt injection
      const sanitizedAttachments = attachments.map((a) => {
        const result = sanitizeExternalContext(a.content, 'attachment');
        return `[Attachment: ${a.name}]\n${result.sanitized}`;
      });
      messageContent = messageContent + '\n\n' + sanitizedAttachments.join('\n\n');
    }

    const userMessage: ChatMessage = {
      id: nanoid(),
      role: 'user',
      content: messageContent,
      timestamp: Date.now(),
      agentType,
    };

    const newMessages = [...messagesRef.current, userMessage];
    setMessages(newMessages);
    if (!overrideContent) {
      setInput('');
      setAttachments([]);
    }
    setIsStreaming(true);

    const assistantMessage: ChatMessage = {
      id: nanoid(),
      role: 'assistant',
      content: '',
      timestamp: Date.now(),
      isStreaming: true,
      agentType,
    };

    setMessages([...newMessages, assistantMessage]);

    const title = newMessages.length <= 1
      ? userMessage.content.slice(0, 60) + (userMessage.content.length > 60 ? '...' : '')
      : conversationTitle;
    if (newMessages.length === 1) setConversationTitle(title);

    try {
      const { systemPrompt, documents, searchUsed } = await buildAIContext(userMessage.content);

      // ── AbortController for the entire send lifecycle (loop + streaming) ──
      loopAbortRef.current = new AbortController();
      const sendSignal = loopAbortRef.current.signal;

      // ── Operating Loop (complex tasks > 0.8) ──
      let enrichedSystemPrompt = systemPrompt;
      const taskAnalysis = analyzeTask(userMessage.content);
      if (taskAnalysis.complexity > 0.8) {
        const providerId = configuredProviders.length > 0 ? configuredProviders[0] : 'groq';
        const callAI = async (prompt: string, sysPrompt?: string): Promise<{ text: string; tokens: number }> => {
          const res = await fetch('/api/ai/chat', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'x-oracle-provider-id': providerId,
              ...csrfHeaders(),
            },
            body: JSON.stringify({
              messages: [{ role: 'user', content: prompt }],
              systemPrompt: sysPrompt || AGENT_SYSTEM_PROMPTS[agentType],
              stream: false,
              maxTokens: 2000,
            }),
            signal: sendSignal,
          });
          if (!res.ok) throw new Error(`AI call failed: ${res.status}`);
          const data = await res.json();
          return { text: data.text || '', tokens: (data.inputTokens || 0) + (data.outputTokens || 0) };
        };

        // ── Real-time operating loop with step-by-step progress ──
        setActiveLoopProgress([]);
        setActiveLoopTask(userMessage.content);
        setIsLoopActive(true);
        const loopProgressRef: OperatingLoopResult[] = [];

        const loopResults = await runOperatingLoop(userMessage.content, callAI, (stepResult, completed, total) => {
          loopProgressRef.push(stepResult);
          setActiveLoopProgress([...loopProgressRef]);
        }, sendSignal);

        setIsLoopActive(false);
        setOperatingLoopResults((prev) => ({ ...prev, [assistantMessage.id]: loopResults }));

        // Dispatch event so Sidebar can show the last completed loop
        window.dispatchEvent(new CustomEvent('oracle-loop-complete', {
          detail: { results: loopResults, total: 6, task: userMessage.content, timestamp: Date.now() },
        }));

        // Inject loop context into system prompt
        const loopContext = loopResults
          .filter((r) => !r.output.startsWith('[Failed'))
          .map((r) => `### ${r.step.toUpperCase()} (${r.agentUsed})\n${r.output}`)
          .join('\n\n');
        if (loopContext) {
          enrichedSystemPrompt = (enrichedSystemPrompt || '') +
            '\n\n## Operating Loop Pre-Analysis (6-step quality process)\n' +
            'The following analysis was completed before your response. Use it to inform your answer:\n\n' +
            loopContext;
        }
      }

      const routeMessages = getOptimizedMessages([...newMessages, assistantMessage]);
      const routeOptions = {
        messages: routeMessages,
        systemPrompt: enrichedSystemPrompt,
      };

      if (streamingEnabled) {
        let fullText = '';
        let capturedProviderId = '';
        let capturedModelId = '';
        let capturedHealth: { latencyMs: number; success: boolean } | null = null;

        const providerId = configuredProviders.length > 0 ? configuredProviders[0] : 'groq';

        const proxyResponse = await fetch('/api/ai/chat', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'x-oracle-provider-id': providerId,
            ...csrfHeaders(),
          },
          body: JSON.stringify({
            messages: routeMessages,
            systemPrompt: routeOptions.systemPrompt,
            stream: true,
          }),
          signal: sendSignal,
        });

        if (!proxyResponse.ok) {
          const errorData = await proxyResponse.json().catch(() => ({ error: 'Proxy request failed' }));

          // Handle daily limit exceeded
          if (errorData.code === 'DAILY_LIMIT_EXCEEDED') {
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantMessage.id
                  ? { ...m, content: `📊 Daily limit reached (${errorData.used}/${errorData.limit}). Upgrade your plan for unlimited requests.`, isStreaming: false }
                  : m
              )
            );
            setIsStreaming(false);
            toast.error('🚫 Daily limit reached — Upgrade your plan for unlimited AI requests', { duration: 5000, icon: '🚫' });
            fetchDailyUsage(); // Refresh usage counter
            return;
          }

          throw new Error(errorData.error || `AI proxy error (${proxyResponse.status})`);
        }

        const reader = proxyResponse.body?.getReader();
        const decoder = new TextDecoder();
        let sseBuffer = '';

        if (reader) {
          while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            sseBuffer += decoder.decode(value, { stream: true });
            const lines = sseBuffer.split('\n');
            sseBuffer = lines.pop() || '';
            for (const line of lines) {
              if (!line.startsWith('data: ')) continue;
              const data = line.slice(6).trim();
              if (data === '[DONE]') continue;
              try {
                const parsed = JSON.parse(data);
                if (parsed.error) throw new Error(parsed.error);
                if (parsed._health) {
                  capturedHealth = { latencyMs: parsed._health.latencyMs, success: parsed._health.success };
                }
                if (parsed.chunk) {
                  fullText += parsed.chunk;
                  capturedProviderId = providerId;
                  if (parsed.model) capturedModelId = parsed.model;
                  setMessages((prev) =>
                    prev.map((m) =>
                      m.id === assistantMessage.id ? { ...m, content: fullText } : m
                    )
                  );
                }
              } catch (e) {
                if (e instanceof Error && e.message && !e.message.includes('JSON')) throw e;
              }
            }
          }
        }

        const inputTokens = estimateTokens(userMessage.content);
        const outputTokens = estimateTokens(fullText);
        const finalProvider = capturedProviderId || 'unknown';
        const finalModel = capturedModelId || 'unknown';

        const completedAssistant = {
          ...assistantMessage,
          content: fullText,
          provider: finalProvider,
          model: finalModel,
          tokensUsed: inputTokens + outputTokens,
          isStreaming: false,
          searchUsed,
        };

        setMessages((prev) =>
          prev.map((m) => m.id === assistantMessage.id ? completedAssistant : m)
        );

        recordUsage(finalProvider, finalModel, inputTokens, outputTokens, 0);

        // Record provider health (client-side, localStorage)
        recordProviderHealth({
          providerId: finalProvider,
          timestamp: Date.now(),
          latencyMs: capturedHealth?.latencyMs ?? 0,
          success: capturedHealth?.success ?? (fullText.length > 0),
          model: finalModel,
          tokensUsed: inputTokens + outputTokens,
        });

        const finalMessages = [...newMessages, completedAssistant];
        saveConversation(finalMessages, title, agentType);

        scoreResponse(userMessage.content, fullText, assistantMessage.id).then((scoredResult) => {
          if (scoredResult) attachQualityToTraining(finalProvider, finalModel, agentType, scoredResult);
        });

        runGuardCheck(userMessage.content, fullText, assistantMessage.id, documents);
        runOutputEval(fullText, assistantMessage.id);
        runEditorCheck(userMessage.content, fullText, assistantMessage.id);
        runAgencyQualityGate(userMessage.content, fullText, assistantMessage.id);

        recordTask({
          taskType: agentType,
          domain: 'general',
          promptPreview: userMessage.content.slice(0, 200),
          responsePreview: fullText.slice(0, 200),
          provider: finalProvider,
          model: finalModel,
          wasSuccessful: fullText.length > 0,
          tags: [agentType, finalProvider],
        });

        // Refresh daily usage after successful request
        fetchDailyUsage();

      } else {
        const providerId = configuredProviders.length > 0 ? configuredProviders[0] : 'groq';

        const proxyResponse = await fetch('/api/ai/chat', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'x-oracle-provider-id': providerId,
            ...csrfHeaders(),
          },
          body: JSON.stringify({
            messages: routeMessages,
            systemPrompt: routeOptions.systemPrompt,
            stream: false,
          }),
          signal: sendSignal,
        });

        if (!proxyResponse.ok) {
          const errorData = await proxyResponse.json().catch(() => ({ error: 'Proxy request failed' }));

          // Handle daily limit exceeded
          if (errorData.code === 'DAILY_LIMIT_EXCEEDED') {
            setMessages((prev) =>
              prev.map((m) =>
                m.id === assistantMessage.id
                  ? { ...m, content: `📊 Daily limit reached (${errorData.used}/${errorData.limit}). Upgrade your plan for unlimited requests.`, isStreaming: false }
                  : m
              )
            );
            setIsStreaming(false);
            toast.error('🚫 Daily limit reached — Upgrade your plan for unlimited AI requests', { duration: 5000, icon: '🚫' });
            fetchDailyUsage();
            return;
          }

          throw new Error(errorData.error || `AI proxy error (${proxyResponse.status})`);
        }

        const proxyResult = await proxyResponse.json();
        const result = {
          text: proxyResult.text || '',
          provider: proxyResult.provider || providerId,
          model: proxyResult.model || providerId,
          inputTokens: proxyResult.inputTokens || 0,
          outputTokens: proxyResult.outputTokens || 0,
          costUSD: proxyResult.costUSD || 0,
        };

        const completedAssistant = {
          ...assistantMessage,
          content: result.text,
          provider: result.provider,
          model: result.model,
          tokensUsed: result.inputTokens + result.outputTokens,
          costUSD: result.costUSD,
          isStreaming: false,
          searchUsed,
        };

        setMessages((prev) =>
          prev.map((m) => m.id === assistantMessage.id ? completedAssistant : m)
        );

        recordUsage(result.provider, result.model, result.inputTokens, result.outputTokens, result.costUSD);

        // Record provider health (client-side, localStorage)
        recordProviderHealth({
          providerId: result.provider,
          timestamp: Date.now(),
          latencyMs: proxyResult._health?.latencyMs ?? 0,
          success: proxyResult._health?.success ?? (result.text.length > 0),
          model: result.model,
          tokensUsed: result.inputTokens + result.outputTokens,
        });

        const finalMessages = [...newMessages, completedAssistant];
        saveConversation(finalMessages, title, agentType);

        scoreResponse(userMessage.content, result.text, assistantMessage.id).then((scoredResult) => {
          if (scoredResult) attachQualityToTraining(result.provider, result.model, agentType, scoredResult);
        });

        runGuardCheck(userMessage.content, result.text, assistantMessage.id, documents);
        runOutputEval(result.text, assistantMessage.id);
        runEditorCheck(userMessage.content, result.text, assistantMessage.id);
        runAgencyQualityGate(userMessage.content, result.text, assistantMessage.id);

        recordTask({
          taskType: agentType,
          domain: 'general',
          promptPreview: userMessage.content.slice(0, 200),
          responsePreview: result.text.slice(0, 200),
          provider: result.provider,
          model: result.model,
          wasSuccessful: result.text.length > 0,
          tags: [agentType, result.provider],
        });

        // Refresh daily usage after successful request
        fetchDailyUsage();
      }
    } catch (err) {
      // Record health on error (client-side, localStorage)
      recordProviderHealth({
        providerId: configuredProviders[0] || 'unknown',
        timestamp: Date.now(),
        latencyMs: 0,
        success: false,
        model: 'unknown',
        tokensUsed: 0,
        errorMessage: err instanceof Error ? err.message : 'Unknown error',
      });
      setMessages((prev) =>
        prev.map((m) =>
          m.id === assistantMessage.id
            ? { ...m, content: `Error: ${err instanceof Error ? err.message : 'Unknown error'}`, isStreaming: false }
            : m
        )
      );
    } finally {
      loopAbortRef.current = null;
      setIsStreaming(false);
    }
  }, [input, isStreaming, streamingEnabled, agentType, conversationTitle, buildAIContext, recordUsage, saveConversation, scoreResponse, runGuardCheck, runOutputEval, runEditorCheck, runAgencyQualityGate, attachments, getOptimizedMessages, webSearchEnabled, configuredProviders]);

  // ── Regenerate Response ──
  const handleRegenerate = useCallback((assistantMsgId: string) => {
    if (isStreaming) return;
    const msgIndex = messages.findIndex((m) => m.id === assistantMsgId);
    if (msgIndex < 0) return;
    let userMsgIndex = -1;
    for (let i = msgIndex - 1; i >= 0; i--) {
      if (messages[i].role === 'user') { userMsgIndex = i; break; }
    }
    if (userMsgIndex < 0) return;
    const userMessage = messages[userMsgIndex];
    const trimmedMessages = messages.slice(0, msgIndex);
    messagesRef.current = trimmedMessages;
    setMessages(trimmedMessages);
    // Mark for full sync so the trimmed DB state replaces the old array
    needsFullSyncRef.current = true;
    handleSend(userMessage.content);
  }, [messages, isStreaming, handleSend]);

  // ── Branch Conversation ──
  const handleBranch = useCallback((branchFromMsgId: string) => {
    if (isStreaming) return;
    const msgIndex = messages.findIndex((m) => m.id === branchFromMsgId);
    if (msgIndex < 0) return;
    const branchMessages = messages.slice(0, msgIndex);
    messagesRef.current = branchMessages;
    setMessages(branchMessages);
    // Mark for full sync so the branched DB state replaces the old array
    needsFullSyncRef.current = true;
    toast.success('🔀 Branched conversation — type a new message to continue from this point', TOAST_DEFAULTS);
  }, [messages, isStreaming]);

  // ── Feedback ──
  const handleFeedback = useCallback((msgId: string, type: 'good' | 'bad') => {
    setFeedback((prev) => {
      const next = { ...prev };
      if (next[msgId] === type) {
        delete next[msgId];
      } else {
        next[msgId] = type;
      }
      return next;
    });
    // Wire feedback → model performance learning
    const msg = messagesRef.current.find((m) => m.id === msgId);
    if (msg && msg.role === 'assistant' && msg.provider && msg.model) {
      recordMessageFeedback(msg.provider, msg.model, agentType, msg.qualityScore, type === 'good' ? 'good' : 'bad');
    }
  }, [agentType]);

  // ── Quick Start Card Click ──
  const handleQuickStart = (prompt: string) => {
    setInput(prompt);
    inputRef.current?.focus();
  };

  // ── Abort operating loop on unmount ──
  useEffect(() => {
    return () => {
      if (loopAbortRef.current) {
        loopAbortRef.current.abort();
        loopAbortRef.current = null;
      }
    };
  }, []);

  // ── Listen for Quick Actions from Sidebar ──
  useEffect(() => {
    const handler = (e: Event) => {
      const detail = (e as CustomEvent).detail;
      if (detail?.prompt) {
        setInput(detail.prompt);
        setTimeout(() => inputRef.current?.focus(), 100);
      }
    };
    window.addEventListener('oracle-quick-action', handler);
    return () => window.removeEventListener('oracle-quick-action', handler);
  }, []);

  // ── Listen for Web Search toggle from AppShell/Sidebar ──
  useEffect(() => {
    const handler = (e: Event) => {
      const detail = (e as CustomEvent).detail;
      if (typeof detail?.enabled === 'boolean') {
        setWebSearchEnabled(detail.enabled);
      }
    };
    window.addEventListener('oracle-web-search-toggle', handler);
    return () => window.removeEventListener('oracle-web-search-toggle', handler);
  }, []);

  // ── File Attachment Handler ──
  const handleFileAttach = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    for (const file of files) {
      try {
        const doc = await processDocument(file);
        indexDocument(doc).catch(() => {}); // fire-and-forget embedding indexing
        setAttachments((prev) => [...prev, { name: file.name, content: doc.content }]);
      } catch {
        toast.error('❌ Failed to read file', TOAST_DEFAULTS);
        const text = await file.text().catch(() => '[Could not read file]');
        setAttachments((prev) => [...prev, { name: file.name, content: text }]);
      }
    }
    e.target.value = '';
  }, []);

  return (
    <div className="flex h-full flex-col" onDragOver={handleDragOver} onDragLeave={handleDragLeave} onDrop={handleDrop}>
      {/* ── Chat Header ── */}
      <ChatHeader
        title={conversationTitle}
        agentType={agentType}
        projects={projects}
        selectedProjectId={selectedProjectId}
        showAgentSelector={showAgentSelector}
        showConversationList={showConversationList}
        showProjectSelector={showProjectSelector}
        conversations={conversations}
        onToggleAgentSelector={() => setShowAgentSelector((p) => !p)}
        onToggleConversationList={() => setShowConversationList((p) => !p)}
        onToggleProjectSelector={() => setShowProjectSelector((p) => !p)}
        onSelectAgent={(type) => { setAgentType(type); setShowAgentSelector(false); }}
        onSelectProject={(id) => { setSelectedProjectId(id); setShowProjectSelector(false); }}
        onSelectConversation={loadConversation}
        onExportPDF={handleExportPDF}
        onExportWord={handleExportWord}
        messageCount={messages.length}
        onNewChat={newConversation}
        onDeleteConversation={async (id) => {
          await conversationsApi.delete(id);
          if (activeConversationId === id) newConversation();
          refreshConversations();
        }}
      />

      {/* ── Messages Area ── */}
      <div className="flex-1 overflow-y-auto px-3 sm:px-4 py-4 sm:py-6" role="log" aria-label="Chat messages" aria-live="polite">
        {messages.length === 0 ? (
          <EmptyState onQuickStart={handleQuickStart} />
        ) : (
          <div className="mx-auto max-w-3xl space-y-3 sm:space-y-4 md:space-y-6">
            <AnimatePresence mode="popLayout">
              {messages.map((msg) => (
                <MessageBubble
                  key={msg.id}
                  message={msg}
                  qualityScore={qualityScores[msg.id]}
                  guardResult={guardResults[msg.id]}
                  evalResult={evalResults[msg.id]}
                  editorResult={editorResults[msg.id]}
                  qualityGateResult={qualityGateResults[msg.id]}
                  operatingLoopResult={operatingLoopResults[msg.id]}
                  feedback={feedback[msg.id]}
                  isStarred={!!starredMessages[msg.id]}
                  onRegenerate={msg.role === 'assistant' && !isStreaming ? () => handleRegenerate(msg.id) : undefined}
                  onBranch={msg.role === 'user' && !isStreaming ? () => handleBranch(msg.id) : undefined}
                  onStar={() => handleStar(msg.id)}
                  onGood={msg.role === 'assistant' ? () => handleFeedback(msg.id, 'good') : undefined}
                  onBad={msg.role === 'assistant' ? () => handleFeedback(msg.id, 'bad') : undefined}
                />
              ))}
            </AnimatePresence>
            {/* Operating loop step dots — shown inline during active loop */}
            {isLoopActive && activeLoopProgress.length > 0 && (
              <OperatingLoopStepDots results={activeLoopProgress} totalSteps={6} isActive={true} />
            )}
            {/* Branded loading spinner when waiting for response */}
            {isStreaming && messages[messages.length - 1]?.content === '' && !isLoopActive && (
              <div className="flex justify-start">
                <div className="oracle-msg-agent rounded-2xl rounded-bl-md px-4 py-3">
                  <div className="oracle-spinner" style={{ flexDirection: 'row', gap: '8px' }}>
                    <div className="oracle-spinner-ring" style={{ width: '16px', height: '16px', borderWidth: '2px' }} />
                    <span className="oracle-spinner-text" style={{ fontSize: '12px' }}>Thinking...</span>
                  </div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        )}
      </div>

      {/* ── Guard Stats ── */}
      {Object.keys(guardResults).length > 0 && (
        <GuardStatsPanel guardResults={guardResults} />
      )}

      {/* ── Floating Operating Loop Progress ── */}
      <AnimatePresence>
        {isLoopActive && activeLoopProgress.length > 0 && (
          <OperatingLoopFloatingProgress
            results={activeLoopProgress}
            totalSteps={6}
            isActive={isLoopActive}
            task={activeLoopTask}
          />
        )}
      </AnimatePresence>

      {/* ── Input Area ── */}
      <ChatInputArea
        input={input}
        setInput={setInput}
        isStreaming={isStreaming}
        agentType={agentType}
        setAgentType={setAgentType}
        attachments={attachments}
        setAttachments={setAttachments}
        estimatedCost={estimatedCost}
        detectedPatterns={detectedPatterns}
        crossDomainSuggestions={crossDomainSuggestions}
        dailyUsage={dailyUsage}
        onSend={handleSend}
        onPaste={handlePaste}
        onFileAttach={handleFileAttach}
        onSidebarToggle={onSidebarToggle}
        sidebarOpen={sidebarOpen}
      />
    </div>
  );
}

