// ─── Plan Hierarchy ───────────────────

const PLAN_HIERARCHY: PlanId[] = ['starter', 'pro', 'agency'];

function planMeetsRequired(current: PlanId, required: PlanId): boolean {
  return PLAN_HIERARCHY.indexOf(current) >= PLAN_HIERARCHY.indexOf(required);
}

