  return AGENT_REQUIRED_PLAN[agentType] || 'starter';
}

/** Get the required plan for a given feature */
export function getRequiredPlanForFeature(feature: string): PlanId {
  return FEATURE_REQUIRED_PLAN[feature] || 'starter';
}

