                </div>
              </div>
            </div>
          </motion.div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useCallback, useMemo } from 'react';
import {motion} from 'framer-motion';
import { motionVariants, transitions, buttonTapProps } from '@/styles/design-tokens';
