                            {trend.momentum.toUpperCase()}
                          </span>
                          <span className="text-[10px] text-[var(--oracle-text-muted)]">{trend.category}</span>
                          <span className="ml-auto text-[10px] text-[var(--oracle-text-muted)]">Relevance: {trend.relevance}%</span>
