                      ))}
                    </div>
                  </div>
                  <div className="flex gap-2 justify-end">
                    <button onClick={() => setShowCreate(false)} className="rounded-lg border border-[var(--oracle-border)] px-4 py-2 text-[12px] text-[var(--oracle-text-3)]">Cancel</button>
